    vocabulary: [['Key', 'The saved value being inserted, not a permanent array index.'], ['Shift', 'Copy one prefix value to the next cell; it temporarily leaves duplicate cells.'], ['Gap', 'The cell at j + 1 where the held key will be placed.'], ['i', 'Original index of the next key.'], ['j', 'Backwards-moving index within the sorted prefix.']],
    invariant: 'Before outer iteration i, prefix 0..i-1 is sorted. The key remains saved while larger prefix values shift; after insertion prefix 0..i is sorted.',
