    costs: [['Best / average / worst', 'O(n log n)', 'The standard implementation still splits and merges sorted input.'], ['Auxiliary arrays', 'O(n) peak', 'The largest merge needs n temporary cells.'], ['Call stack', 'O(log n)', 'Only one root-to-leaf path is active at once.'], ['Stable / in place / adaptive', 'Yes / no / no', 'Left-first ties preserve equals; the taught form allocates temp; no ordered-range shortcut.']],
    descending: 'Use arr[left] >= arr[right] to choose the left run. Both children must also be sorted descending; left-first equality still preserves stability.',
    mistakes: [['Right child starts at mid', 'Ranges overlap and may not shrink.', 'Use mid + 1.'], ['Merge before both calls return', 'Input runs are not yet known to be sorted.', 'Call left, call right, then merge.'], ['Ignore leftovers', 'Values vanish when one run becomes empty.', 'Copy the remaining suffix without key comparisons.'], ['Copy temp[k] to arr[k]', 'A nonzero-start merge overwrites the wrong range.', 'Write arr[start + k].'], ['Use < instead of <=', 'Equal right-run records can cross earlier left records.', 'Choose the left record on ties.']],
